import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as r,o,j as a,G as t,ae as n,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Modernizing Access to our Public Waters Act of 2025","description":"","frontmatter":{"legisId":"2025-12-26-modernizing-access-to-our-public-waters-act-of-2025","title":"Modernizing Access to our Public Waters Act of 2025","displayTitle":"Modernizing Access to our Public Waters Act of 2025","lawNumber":"119-62","billNumber":"H.R. 187","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ62.xml","publishDate":"2025-12-26T00:00:00-05:00","industries":["environment","technology","government-operations"],"agencies":["Department of Agriculture","Department of the Interior"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Modernizing Access to our Public Waters Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Modernizing Access to our Public Waters Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025\\",\\"datePublished\\":\\"2025-12-26T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025.md","filePath":"congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2025-12-26-modernizing-access-to-our-public-waters-act-of-2025.md"},f=Object.assign(c,{setup(d){return(u,e)=>(o(),r("div",null,[e[0]||(e[0]=a("h1",{id:"modernizing-access-to-our-public-waters-act-of-2025",tabindex:"-1"},[l("Modernizing Access to our Public Waters Act of 2025 "),a("a",{class:"header-anchor",href:"#modernizing-access-to-our-public-waters-act-of-2025","aria-label":'Permalink to "Modernizing Access to our Public Waters Act of 2025"'},"​")],-1)),t(i),t(s,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Friday, December 26, 2025. Public Law 119-62, H.R. 187.</p><p><strong>Headline:</strong> Federal agencies must standardize, digitize, and publish maps of recreational access and restrictions on federally managed waterways.</p><p><strong>Why it matters:</strong> The law gives the public clearer, regularly updated information on where and how waterways can be accessed, navigated, and fished without changing existing access rights or regulatory authority.</p><p><strong>What the law does:</strong></p><ul><li>Requires the Agriculture and Interior Departments to adopt compatible mapping-data standards within 30 months.</li><li>Requires online maps within five years, where practicable, covering closures, restrictions, permitted recreational uses, access facilities, navigation information, and fishing limits.</li><li>Requires access and navigation data updates at least twice yearly and fishing-restriction updates as changes take effect.</li><li>Creates a process for public questions and comments and allows coordination with state, Tribal, nonprofit, private-sector, and federal partners.</li><li>Encourages use of existing maps and data while protecting sensitive historic and archaeological information.</li></ul><p><strong>Who it affects:</strong></p><ul><li>People who boat, fish, paddle, or otherwise use federally managed waterways.</li><li>Federal land and water managers and their state, Tribal, nonprofit, and private-sector partners.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Online maps will make it easier to find water access points, permitted activities, navigation details, closures, and fishing restrictions.</li><li>More frequent updates and a public feedback process will help users plan trips using current information.</li></ul><p><strong>Context:</strong> The law excludes irrigation canals and flowage easements and does not alter water access, fisheries management, or federal and state regulatory authority.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="modernizing-access-to-our-public-waters-act-of-2025-1" tabindex="-1">Modernizing Access to our Public Waters Act of 2025 <a class="header-anchor" href="#modernizing-access-to-our-public-waters-act-of-2025-1" aria-label="Permalink to &quot;Modernizing Access to our Public Waters Act of 2025&quot;">​</a></h3><p>The MAPWaters Act requires federal agencies to standardize, digitize, and publish online mapping data about recreational access to federally managed waterways, waterway restrictions, and fishing restrictions. It also requires regular updates, public feedback options, interagency coordination, and annual progress reports while leaving existing water access, regulatory authority, and fisheries management unchanged.</p><p><strong>Key takeaways:</strong></p><ul><li>The Agriculture and Interior Departments must adopt compatible interagency data standards within 30 months of enactment.</li><li>Within five years, the departments must publish online mapping data, where practicable, covering waterway closures and restrictions, permitted recreational uses, access facilities, navigation information, and fishing restrictions.</li><li>Waterway access and navigation data must be updated at least twice a year, while fishing restriction data must be updated in real time as changes take effect.</li><li>The departments must provide a process for public questions and comments about waterway restrictions and access and navigation information.</li><li>The departments may work with state, Tribal, nonprofit, private-sector, and federal partners and should use existing maps and data where practicable.</li><li>The Act excludes irrigation canals and flowage easements, protects sensitive historic and archaeological information, and does not change existing water access or federal and state regulatory authority.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ62.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ62.xml</a></p>',16))]))}});export{h as __pageData,f as default};
